class Solution {
    private int[] a;

    public int[] sortKColours(int[] balls, int k) {
        a = balls.clone();
        sort(0, a.length - 1, 1, k);
        return a;
    }

    private void sort(int left, int right, int lo, int hi) {
        if (left >= right || lo >= hi) return;
        int mid = (lo + hi) / 2, i = left, j = right;
        while (i <= j) {
            while (i <= j && a[i] <= mid) i++;
            while (i <= j && a[j] > mid) j--;
            if (i < j) { int t = a[i]; a[i] = a[j]; a[j] = t; }
        }
        sort(left, j, lo, mid);
        sort(i, right, mid + 1, hi);
    }
}

