class Solution {
    vector<int> a;

    void sort(int left, int right, int lo, int hi) {
        if (left >= right || lo >= hi) return;
        int mid = (lo + hi) / 2, i = left, j = right;
        while (i <= j) {
            while (i <= j && a[i] <= mid) i++;
            while (i <= j && a[j] > mid) j--;
            if (i < j) swap(a[i], a[j]);
        }
        sort(left, j, lo, mid);
        sort(i, right, mid + 1, hi);
    }

public:
    vector<int> sortKColours(vector<int>& balls, int k) {
        a = balls;
        sort(0, (int) a.size() - 1, 1, k);
        return a;
    }
};

