static void sort_range(int* a, int left, int right, int lo, int hi) {
    if (left >= right || lo >= hi) return;
    int mid = (lo + hi) / 2, i = left, j = right;
    while (i <= j) {
        while (i <= j && a[i] <= mid) i++;
        while (i <= j && a[j] > mid) j--;
        if (i < j) { int t = a[i]; a[i] = a[j]; a[j] = t; }
    }
    sort_range(a, left, j, lo, mid);
    sort_range(a, i, right, mid + 1, hi);
}

int* sortKColours(int* balls, int ballsSize, int k, int* returnSize) {
    int* a = malloc(ballsSize * sizeof(int));
    memcpy(a, balls, ballsSize * sizeof(int));
    sort_range(a, 0, ballsSize - 1, 1, k);
    *returnSize = ballsSize;
    return a;
}
